/*
 * A266298  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 14" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A266298
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   a(n) = 1 if ((n - ⌊√n⌋²) < 2), otherwise 0. The sequence is read
 *            row‑by‑row from the Rule 14 cellular automaton triangle; each
 *            row r has length 2r+1, with the first two cells 1 (except row 0,
 *            which has a single 1). The integer part of √n gives the row
 *            number r, and the offset j = n – r² yields th...
 * Range:     u8 n <= 9999, u16 n <= 9999, u32 n <= 9999, u64 n <= 9999,
 *            u128 n <= 9999, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* integer floor sqrt of n (fits in 32 bits for 64-bit n) */
    idx_t lo = 0, hi = 0xFFFFFFFFULL;      /* 2^32 – 1 */
    while (lo <= hi) {
        idx_t mid = lo + ((hi - lo) >> 1);
        idx_t sq  = mid * mid;
        if (sq <= n)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    idx_t r = hi;                /* floor(sqrt(n)) */
    idx_t j = n - r * r;         /* offset within the row */
    return (seq_t)(j < 2);       /* 1 for the first two cells, else 0 */
}
